const app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let q='',filter='전체',sort='기본순',saved=[];try{saved=JSON.parse(localStorage.getItem('theme-wiki-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
const number=n=>Number(n).toLocaleString('ko-KR');
function av(p,cl=''){return `<span class="avatar ${cl}" role="img" aria-label="${esc(p.name)} 창작 아바타" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%"></span>`}
const badge=t=>`<span class="badge">${esc(t)}</span>`;
function evidence(ids=[]){if(!ids.length)return '';return `<details class="evidence"><summary>대화 근거 보기 <span>${ids.length}개</span></summary><div class="quotes">${ids.map(id=>{const s=wiki.sources[id];return `<blockquote><div><b>${esc(s.user)}</b><time>${esc(s.date)}</time></div><p>${esc(s.text)}</p><small>원본 메시지 ${number(s.row)}번 · CSV 레코드 기준</small></blockquote>`}).join('')}</div></details>`}
function fact(f){return `<div class="factblock">${badge(f.kind)}<h3>${esc(f.title)}</h3><p>${esc(f.text)}</p>${evidence(f.ids)}</div>`}
function eventCard(e,full=false){return `<article class="event ${full?'full':''}"><div class="eventmeta"><time>${e.date}</time>${badge(e.kind)}</div><h3><a href="#event/${e.id}">${esc(e.title)} <span>↗</span></a></h3><p>${esc(e.text)}</p><div class="participants">${e.persons.map(id=>`<a href="#person/${id}">${av(people[id])}<span>${people[id].name}</span></a>`).join('')}</div>${full?evidence(e.ids):`<a class="textlink" href="#event/${e.id}">대화와 함께 읽기 →</a>`}</article>`}
function card(p){return `<article class="personcard"><a class="cardmain" href="#person/${p.id}"><div class="portrait">${av(p)}<span class="cardnumber">NO. ${String(p.id+1).padStart(2,'0')}</span></div><div class="cardcopy"><small>${esc(p.user)}</small><h3>${p.name}</h3><p>${esc(p.line)}</p><div class="tags">${p.tags.map(t=>badge(t)).join('')}</div></div></a><div class="cardfoot"><span>에피소드 ${p.events.length} · 메시지 ${number(p.count)}</span><button class="star" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${p.name} 북마크">${saved.includes(p.id)?'★':'☆'}</button></div></article>`}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">개별의 테마천국 · 대화로 쓰는 우리 위키</div><h1>사람은 성격 네 글자보다<br><em>같이 겪은 이야기.</em></h1><p>좋아하는 팀, 같이 갔던 곳, 아직도 꺼내는 그날 이야기.<br>단톡방의 기록에서 한 사람씩 다시 만나봅니다.</p><a href="#events" class="btn primary">옛날 이야기 읽기 ↗</a></div><div class="heroart">${[people[0],people[3],people[4]].map(p=>av(p)).join('')}<span>그때 그 얘기, 기억나?</span></div></section><div class="stats"><div><strong>12</strong><span>인물 문서</span></div><div><strong>${wiki.events.length}</strong><span>근거가 있는 에피소드</span></div><div><strong>2023—26</strong><span>대화 아카이브</span></div><a href="#guide">기록 기준 보기 ↗</a></div><section><div class="sectionhead"><div><div class="eyebrow">PEOPLE</div><h2>인물도감</h2></div><a href="#compare" class="textlink">두 사람 비교 ↗</a></div><div class="toolbar"><div class="filters">${['전체','야구','축구','게임','여행','술·음식','러닝','내 도감'].map(t=>`<button data-filter="${t}" class="chip ${filter===t?'active':''}">${t}</button>`).join('')}</div><div class="searchwrap"><input id="search" type="search" aria-label="이름, 취향, 사건 검색" placeholder="이름, 취향, 사건 검색" value="${esc(q)}"><select id="sort" aria-label="인물 정렬">${['기본순','발언 많은 순','이름순'].map(s=>`<option ${sort===s?'selected':''}>${s}</option>`).join('')}</select></div></div><p id="resultcount" class="subtle" aria-live="polite"></p><div class="grid" id="cards"></div></section><section class="featured"><div class="sectionhead"><div><div class="eyebrow">REMEMBER WHEN</div><h2>아직도 꺼내는 그 이야기</h2></div><a href="#events" class="textlink">전체 ${wiki.events.length}개 보기 →</a></div><div class="eventgrid">${['cafe','japan','odyssey'].map(id=>eventCard(wiki.events.find(e=>e.id===id))).join('')}</div></section><aside class="note"><b>한 줄의 농담을 한 사람의 성격으로 만들지 않기.</b><p>직접 밝힌 취향, 서로 회상한 사건, 아직 모르는 내용을 구분했습니다. 사건의 날짜는 대화가 오간 날이며 실제 발생일과 다를 수 있습니다.</p></aside>`;renderCards();document.getElementById('search').addEventListener('input',e=>{q=e.target.value;renderCards()});document.getElementById('sort').addEventListener('change',e=>{sort=e.target.value;renderCards()})}
function searchText(p){return [p.name,p.user,p.line,...p.tags,p.mbti.title,p.football.title,p.football.text,...p.likes.flatMap(f=>[f.title,f.text]),...p.events.map(id=>{const e=wiki.events.find(e=>e.id===id);return e.title+' '+e.text})].join(' ').toLowerCase()}
function renderCards(){const keys={'야구':/야구|두산|KT/,'축구':/축구|아스날|첼시|리버풀/,'게임':/메이플|게임|LoL|로스트아크|오디세이/,'여행':/여행/,'술·음식':/음식|맥주|사케|닭발/,'러닝':/러닝/};let list=people.filter(p=>(filter==='전체'||filter==='내 도감'&&saved.includes(p.id)||keys[filter]?.test(p.tags.join(' ')))&&searchText(p).includes(q.toLowerCase().trim()));if(sort==='발언 많은 순')list.sort((a,b)=>b.count-a.count);if(sort==='이름순')list.sort((a,b)=>a.name.localeCompare(b.name,'ko'));document.getElementById('resultcount').textContent=`${list.length}명의 인물`;document.getElementById('cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty">해당하는 인물이 없어요. 검색어나 분류를 바꿔보세요.</div>'}
function bars(items){const max=Math.max(1,...items.map(x=>x[1]));return `<div class="bars">${items.map(([t,n])=>`<div class="barrow"><span>${esc(t)}</span><div><i style="width:${n/max*100}%"></i></div><b>${number(n)}</b></div>`).join('')}</div>`}
function person(id){const p=people[id];if(!p)return missing();app.innerHTML=`<div class="crumb"><a href="#">인물도감</a> / ${p.name}</div><section class="profilehead">${av(p)}<div><div class="eyebrow">인물 문서 · ${esc(p.user)}</div><h1>${p.name}</h1><p>${esc(p.line)}</p><div class="tags">${p.tags.map(badge).join('')}</div></div><button class="btn" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'★ 내 도감에 저장됨':'☆ 내 도감에 담기'}</button></section><div class="docgrid"><aside class="toc"><small>이 문서의 내용</small>${[['taste','취향과 취미'],['football','축구 취향'],['relations','같이 등장하는 사람'],['stories','사건·추억'],['mbti','MBTI 기록'],['numbers','대화 속 관심 분야']].map(([id,t],i)=>`<button data-section="${id}"><span>0${i+1}</span> ${t}</button>`).join('')}<div class="record"><b>${number(p.count)}</b> 메시지<small>${p.first.slice(0,10)}<br>— ${p.last.slice(0,10)}</small></div></aside><article class="document"><section id="taste"><h2><span>01</span> 취향과 취미</h2><div class="factgrid">${p.likes.map(fact).join('')}</div></section><section id="football"><h2><span>02</span> 축구 취향</h2>${fact(p.football)}${p.players.length?`<details class="statdetail"><summary>대화에 자주 나온 축구선수</summary>${bars(p.players)}<p class="subtle">${wiki.meta.playerMethod}</p></details>`:''}</section><section id="relations"><h2><span>03</span> 같이 등장하는 사람</h2><p class="subtle">친밀도 점수 대신 함께한 일과 실제 대화로 연결했습니다.</p><div class="relationgrid">${p.relations.map(r=>`<div class="relation"><a href="#person/${r.person}">${av(people[r.person])}<div><b>${people[r.person].name}</b><p>${esc(r.text)}</p></div></a>${r.event?`<a class="textlink" href="#event/${r.event}">관련 이야기 →</a>`:evidence(r.ids)}</div>`).join('')}</div>${p.mentions.length?`<details class="statdetail"><summary>직접 @멘션한 상대</summary>${bars(p.mentions)}<p class="subtle">${wiki.meta.mentionMethod}</p></details>`:''}</section><section id="stories"><h2><span>04</span> 사건·추억</h2><div class="storylist">${p.events.map(id=>eventCard(wiki.events.find(e=>e.id===id),true)).join('')}</div></section><section id="mbti"><h2><span>05</span> MBTI 기록</h2>${fact(p.mbti)}<p class="subtle">당시 자기소개·검사 놀이 기록입니다. 현재 성격이나 심리 상태를 진단하지 않습니다.</p></section><section id="numbers"><h2><span>06</span> 대화 속 관심 분야</h2>${bars(p.topics)}<p class="subtle">${wiki.meta.topicMethod}</p><a href="#guide" class="textlink">전체 분석 기준 →</a></section></article></div>`}
function eventsPage(){app.innerHTML=`<section class="pagehead"><div class="eyebrow">THE ARCHIVE</div><h1>사건과 추억</h1><p>같은 날의 기억도 사람마다 조금씩 다르니까.<br>날짜는 사건 발생일이 아닌 <b>이야기를 나눈 날</b>입니다.</p></section><div class="eventgrid archive">${[...wiki.events].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>eventCard(e)).join('')}</div>`}
function eventPage(id){const e=wiki.events.find(e=>e.id===id);if(!e)return missing();app.innerHTML=`<div class="crumb"><a href="#events">사건과 추억</a> / ${esc(e.title)}</div><div class="singleevent">${eventCard(e,true)}<aside class="note">표시 날짜는 이 이야기를 나눈 날짜입니다. 회상은 참여자의 기억이며, 약속·제안은 실제 실행 여부와 구분합니다.</aside><a href="#events" class="btn">← 다른 이야기</a></div>`}
function compare(a=0,b=3){a=Number(a);b=Number(b);if(!people[a])a=0;if(!people[b])b=3;const p=people[a],r=people[b];const common=wiki.events.filter(e=>e.persons.includes(a)&&e.persons.includes(b));app.innerHTML=`<section class="pagehead"><div class="eyebrow">SIDE BY SIDE</div><h1>두 사람, 같이 보기</h1><p>취향을 나란히 보고 함께 등장한 이야기를 찾아봅니다.</p></section><div class="compare"><div class="compareselect">${[a,b].map((v,i)=>`<select id="compare${i}" aria-label="${i+1}번째 인물">${people.map(p=>`<option value="${p.id}" ${p.id===v?'selected':''}>${p.name}</option>`).join('')}</select>`).join('<span>×</span>')}</div><div class="comparegrid">${[p,r].map(p=>`<article class="comparecard">${av(p)}<h2><a href="#person/${p.id}">${p.name} ↗</a></h2><div class="tags">${p.tags.map(badge).join('')}</div><h3>축구</h3><p>${esc(p.football.title)}</p><h3>MBTI 기록</h3><p>${esc(p.mbti.title)}</p><h3>취향</h3><p>${p.likes.map(f=>esc(f.title)).join(' · ')}</p></article>`).join('')}</div><h2 class="sharedtitle">함께 등장한 이야기</h2>${a===b?'<p>서로 다른 두 사람을 선택해보세요.</p>':common.length?common.map(e=>eventCard(e)).join(''):'<p class="empty">이번에 정리한 에피소드에서는 공통 기록을 찾지 못했어요. 친하지 않다는 뜻은 아닙니다.</p>'}</div>`;[0,1].forEach(i=>document.getElementById('compare'+i).addEventListener('change',()=>{location.hash=`compare/${document.getElementById('compare0').value}/${document.getElementById('compare1').value}`}))}
function guide(){app.innerHTML=`<section class="pagehead"><div class="eyebrow">EDITORIAL NOTES</div><h1>어떤 기록인가요?</h1><p>만들어낸 성격 소개에서, 대화로 확인하는 친구들의 위키로.</p></section><article class="guide"><h2>원본과 분석 범위</h2><p>제공된 카카오톡 CSV 전체 ${number(wiki.meta.total)}개 레코드를 구조적으로 읽고, 대상 12명의 메시지 ${number(wiki.meta.peopleMessages)}건을 집계했습니다. 기간은 ${wiki.meta.start}~${wiki.meta.end}입니다. 봇과 기타 발신자는 인물 집계에서 제외했습니다.</p><p>전체 레코드를 프로그램으로 검색한 뒤 사건·취향·MBTI 후보의 앞뒤 대화를 사람이 읽는 방식으로 검토했습니다. 모든 대화의 의미를 빠짐없이 해석한 완전한 인물 전기는 아닙니다. 현재 ${wiki.events.length}개 에피소드와 ${Object.keys(wiki.sources).length}개 근거 메시지를 선별했습니다.</p><h2>확인한 것과 모르는 것</h2><ul><li>본인 발언: 직접 밝힌 당시 취향이나 검사 결과.</li><li>회상: 실제 일어난 날짜가 아니라 회상한 날짜를 표시. 기억이 엇갈리면 양쪽 설명을 함께 수록.</li><li>약속·제안: 실제 방문·실행 완료로 바꾸지 않음.</li><li>선수 평가: 호평이나 언급을 최애·팬 선언으로 바꾸지 않음.</li><li>미확인: MBTI·축구선수 취향 등의 근거가 부족하면 비워둠.</li></ul><h2>통계 읽는 법</h2><p>${wiki.meta.topicMethod}</p><p>${wiki.meta.playerMethod}</p><p>${wiki.meta.mentionMethod}</p><p>메시지 수에는 해당 인물의 짧은 반응·봇 명령·사진 표시가 포함됩니다. 키워드가 없는 연속 단문과 별칭은 놓칠 수 있어 비중이나 성격 점수로 해석하지 않습니다.</p><h2>근거와 이미지</h2><p>근거 보기를 열면 발신자·시간·원문을 확인할 수 있습니다. 원본 메시지 번호는 헤더를 포함한 CSV 레코드 순서이며, 여러 줄 메시지가 있어 물리적 파일 줄 번호와는 다릅니다. 이미지·동영상 자체는 원본 CSV에 없어 해석하지 않았습니다. 아바타는 실제 얼굴과 무관한 창작 이미지입니다.</p><h2>공개 범위</h2><p>원본 CSV 전체는 사이트와 저장소에 포함하지 않습니다. 공개 페이지에는 선별한 취향·게임·모임 이야기와 그 근거만 담았습니다. 수정할 부분은 기록 날짜와 해당 문서를 기준으로 알려주세요.</p><a href="#" class="btn">인물도감으로 →</a></article>`}
function missing(){app.innerHTML='<div class="empty"><h1>문서를 찾을 수 없어요</h1><a href="#">인물도감으로 돌아가기</a></div>'}
function route(){const [kind,id,b]=location.hash.slice(1).split('/');if(kind==='person')person(Number(id));else if(kind==='event')eventPage(id);else if(kind==='events')eventsPage();else if(kind==='compare')compare(id??0,b??3);else if(kind==='guide')guide();else home();document.title=`${kind==='person'&&people[id]?people[id].name+' · ':''}개별의테마천국 위키`;window.scrollTo(0,0)}
app.addEventListener('click',e=>{const s=e.target.closest('[data-save]');if(s){const id=Number(s.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('theme-wiki-saved',JSON.stringify(saved))}catch{}if(document.getElementById('cards'))renderCards();else {s.textContent=saved.includes(id)?'★ 내 도감에 저장됨':'☆ 내 도감에 담기';s.setAttribute('aria-pressed',saved.includes(id))}}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;home()}const sec=e.target.closest('[data-section]');if(sec)document.getElementById(sec.dataset.section)?.scrollIntoView({behavior:'smooth',block:'start'})});
window.addEventListener('hashchange',route);route();
